'use strict';

// MODULES //

var scabs1 = require( '@stdlib/blas/base/scabs1' );


// MAIN //

/**
* Finds the index of the first element having maximum |Re(.)| + |Im(.)|.
*
* @param {PositiveInteger} N - number of indexed elements
* @param {Complex64Array} cx - input array
* @param {integer} strideX - `cx` stride length
* @param {NonNegativeInteger} offsetX - starting index for `cx`
* @returns {integer} index value
*
* @example
* var Complex64Array = require( '@stdlib/array/complex64' );
*
* var cx = new Complex64Array( [ -2.0, 1.0, 3.0, -5.0, 4.0, 0.0, -1.0, -3.0 ] );
*
* var icx = icamax( cx.length, cx, 1, 0 );
* // returns 1
*/
function icamax( N, cx, strideX, offsetX ) {
	var cmax;
	var icx;
	var ix;
	var v;
	var i;

	if ( N < 1 ) {
		return -1;
	}
	icx = 0;
	if ( N === 1 ) {
		return icx;
	}
	cmax = scabs1( cx.get( offsetX ) );
	ix = offsetX + strideX;
	for ( i = 1; i < N; i++ ) {
		v = scabs1( cx.get( ix ) );
		if ( v > cmax ) {
			icx = i;
			cmax = v;
		}
		ix += strideX;
	}
	return icx;
}


// EXPORTS //

module.exports = icamax;
